import { newClient } from "@hunt/public-client";
import React, { type ReactNode, useEffect, useState } from "react";
import apiUrl from "../../../../utils/apiUrl";
import {
  IS_STATIC_SITE,
  staticDisabledMessage,
} from "../../../../utils/staticSite";
import { PULL_COST_MULTIPLIER, NUM_BULK_PULL } from "../constants";
import { type BannerDisplay } from "../types";
import { GachaActionButton } from "./GachaActionButton";
import PullAnimationOverlay from "./PullAnimationOverlay";
import PuzzlePiece from "./PuzzlePiece";

export type PullBannerResult = {
  output?: {
    clue_id?: string;
    puzzle_slug?: string;
    [key: string]: unknown;
  };
  [key: string]: unknown;
};

type PullButtonsProps = {
  numChips: number;
  selectedBanner: string | undefined;
  isBannerEmpty: boolean;
  pullResults: PullBannerResult[] | null;
  setPullResults: React.Dispatch<
    React.SetStateAction<PullBannerResult[] | null>
  >;
  banners: BannerDisplay[];
  onPull?: (args: {
    bannerSlug: string;
    numPulls: number;
  }) => Promise<{ pulls: PullBannerResult[]; error?: string }>;
};

function PullButtons({
  numChips,
  selectedBanner,
  isBannerEmpty,
  pullResults,
  setPullResults,
  banners,
  onPull,
}: PullButtonsProps) {
  const [playAnimationNumPulls, setPlayAnimationNumPulls] = useState<
    "1" | "10" | undefined
  >(undefined);
  const [clueComponents, setClueComponents] = useState<(string | null)[]>([]);
  const [shellComponents, setShellComponents] = useState<ReactNode[]>([]);
  const isStaticSite = IS_STATIC_SITE;

  const noChipsLeft = numChips === 0;
  const notEnoughChips = numChips < NUM_BULK_PULL * PULL_COST_MULTIPLIER;

  // When pullResults changes, fetch clue components for any clues
  useEffect(() => {
    let cancelled = false;
    async function fetchClues() {
      if (!pullResults) {
        setClueComponents([]);
        return;
      }
      const cluePromises = pullResults
        .filter((item) =>
          Boolean(item.output && typeof item.output.clue_id === "string"),
        )
        .map(async (item) => {
          const clueId =
            item.output && typeof item.output.clue_id === "string"
              ? item.output.clue_id
              : null;
          if (clueId === null) {
            throw new Error("bug: expected either clue_id to be set");
          }

          try {
            const clueResponse = await fetch(
              `/rounds/fates_thread_casino/clue/${clueId}/raw`,
            );
            if (clueResponse.ok) {
              return await clueResponse.text();
            } else {
              return null;
            }
          } catch {
            return null;
          }
        });
      const shells = pullResults
        .filter(
          (item) =>
            item.output !== undefined &&
            typeof item.output.puzzle_slug === "string" &&
            typeof item.output.clue_id !== "string",
        )
        .map((item) => {
          const puzzleSlug =
            item.output && typeof item.output.puzzle_slug === "string"
              ? item.output.puzzle_slug
              : null;

          if (puzzleSlug === null) {
            throw new Error("bug: expected puzzle_slug to be set");
          }

          const banner = banners.find(
            (banner) =>
              banner.puzzle1.slug === puzzleSlug ||
              banner.puzzle2.slug === puzzleSlug,
          );
          if (banner === undefined) {
            throw new Error(
              `could not find banner for puzzle slug ${puzzleSlug}`,
            );
          }

          return (
            <PuzzlePiece
              key={puzzleSlug}
              puzzle={
                banner.puzzle1.slug === puzzleSlug
                  ? banner.puzzle1
                  : banner.puzzle2
              }
            />
          );
        });
      setShellComponents(shells);

      const clues = await Promise.all(cluePromises);
      if (!cancelled) {
        setClueComponents(clues);
      }
    }
    if (playAnimationNumPulls && pullResults) {
      void fetchClues();
    } else {
      setClueComponents([]);
    }
    return () => {
      cancelled = true;
    };
  }, [banners, playAnimationNumPulls, pullResults]);

  // Helper for pulling and showing modal
  const handlePull = async (numPulls: number) => {
    if (!selectedBanner) {
      alert("Please select a banner first.");
      return;
    }
    if (isBannerEmpty) {
      alert("This banner is empty - no more pulls available.");
      return;
    }
    if (onPull) {
      try {
        const result = await onPull({
          bannerSlug: selectedBanner,
          numPulls,
        });
        if (result.error) {
          alert("Pull failed: " + result.error);
          return;
        }
        setPullResults(result.pulls);
        setPlayAnimationNumPulls(numPulls === 10 ? "10" : "1");
        return;
      } catch (err) {
        alert("Pull failed: " + String(err));
        return;
      }
    }
    if (isStaticSite) {
      alert(staticDisabledMessage("Pulls"));
      return;
    }
    try {
      const apiClient = newClient(apiUrl(), undefined);
      const result = await apiClient.pullBanner({
        params: { bannerSlug: selectedBanner },
        body: { num_pulls: numPulls },
      });
      if (result.status === 200) {
        setPullResults(result.body.pulls);
        setPlayAnimationNumPulls(numPulls === 10 ? "10" : "1");
      } else if (result.status === 400) {
        alert("Pull failed: " + result.body.error_message);
      } else {
        alert("Pull failed: Unknown error");
      }
    } catch (err) {
      alert("Error calling pullBanner: " + String(err));
    }
  };

  return (
    <>
      {playAnimationNumPulls && (
        <PullAnimationOverlay
          type={playAnimationNumPulls}
          onClose={() => {
            setPlayAnimationNumPulls(undefined);
          }}
          clueComponents={clueComponents}
          shellComponents={shellComponents}
        />
      )}
      <div className="flex flex-row gap-4 pb-10" data-tutorial="pulls">
        <GachaActionButton
          variant="green"
          cost={PULL_COST_MULTIPLIER}
          onClick={() => {
            void handlePull(1);
          }}
          disabledMessage={
            isStaticSite && !onPull
              ? staticDisabledMessage("Pulls")
              : isBannerEmpty
                ? "This banner is empty."
                : noChipsLeft
                  ? "You don't have any chips."
                  : undefined
          }
        >
          Pull x1
        </GachaActionButton>
        <GachaActionButton
          variant="green"
          cost={NUM_BULK_PULL * PULL_COST_MULTIPLIER}
          onClick={() => {
            void handlePull(NUM_BULK_PULL);
          }}
          disabledMessage={
            isStaticSite && !onPull
              ? staticDisabledMessage("Pulls")
              : isBannerEmpty
                ? "This banner is empty."
                : notEnoughChips
                  ? "You don't have enough chips."
                  : undefined
          }
        >
          Pull x{NUM_BULK_PULL}
        </GachaActionButton>
      </div>
    </>
  );
}

export default PullButtons;
