import { cn, Mono } from "@hunt/styled-ui";
import { Lock } from "lucide-react";
import React from "react";
import { NSFWIndicator } from "../../../../components/NSFWIndicator";
import { GRAY_BUTTON_STYLING } from "../gacha_styling";
import { type BannerDisplay } from "../types";
import ShellStatus from "./ShellStatus";

type BannerStatusProps = {
  banner: BannerDisplay;
  numGachaSolves: number;
};

const BANNER_UNLOCK_THRESHOLDS = {
  art: 0,
  words: 0,
  cells: 0,
  charts: 1,
  characters: 3,
};

function BannerStatus({ banner, numGachaSolves }: BannerStatusProps) {
  return (
    <>
      {/* TODO: Split out locked and unlockable states. */}
      {banner.state === "locked" && (
        <div className="flex flex-row flex-1 items-center font-bold text-base text-red-500">
          <Lock className="w-4 h-4 text-red-500 mr-2" strokeWidth={3} />
          {numGachaSolves}/
          {
            BANNER_UNLOCK_THRESHOLDS[
              banner.slug as keyof typeof BANNER_UNLOCK_THRESHOLDS
            ]
          }{" "}
          solves
        </div>
      )}
      {banner.state === "unlocked" && (
        // TODO: The color for the solved shell is bleh, find a better color for it.
        <div className="flex flex-row flex-1 items-center gap-2 mx-2 select-none">
          <ShellStatus puzzle={banner.puzzle1} isFirstPuzzle />
          <ShellStatus puzzle={banner.puzzle2} />
        </div>
      )}
    </>
  );
}

type BannerAnswerProps = {
  state: BannerDisplay;
  selected?: boolean;
};

function BannerAnswer({ state, selected }: BannerAnswerProps) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center text-green-600 text-lg font-bold bg-white/75 mx-2.5 w-36",
        !selected && "mr-3",
      )}
    >
      <Mono className="min-h-[1.5rem]">{state.puzzle1.answer || ""}</Mono>
      <Mono className="min-h-[1.5rem]">{state.puzzle2.answer || ""}</Mono>
    </div>
  );
}

type GachaSidebarItemProps = {
  onClick: () => void;
  banner: BannerDisplay;
  numGachaSolves: number;
  selected?: boolean;
};

function GachaSidebarItem({
  selected,
  onClick,
  banner,
  numGachaSolves,
}: GachaSidebarItemProps) {
  const isLocked = banner.state === "locked";
  const backgroundImageColor = banner.sidebar_asset;
  const backgroundImageGrayscale = banner.sidebar_asset_grayscale;

  return (
    <button
      type="button"
      className={cn(
        "group/sidebar-item flex gap-2 text-left items-center",
        !isLocked && "pr-2.5",
      )}
      onClick={isLocked ? undefined : onClick}
      disabled={isLocked}
    >
      <div
        className={cn(
          "relative h-24 ml-3.5 overflow-visible",
          selected && !isLocked && "ml-0",
        )}
      >
        <div
          className={cn(
            "relative h-24 w-80 text-black rounded-tl-3xl rounded-br-3xl",
            !isLocked &&
              "bg-[#8B9F85] group-hover/sidebar-item:-translate-x-2.5 focus-visible:-translate-x-2.5",
            selected &&
              !isLocked &&
              "group-hover/sidebar-item:translate-x-0 focus-visible:translate-x-0",
            !selected && !isLocked && "shadow-[inset_0_0_12px_0_#FFFFFF80]",
            isLocked && "cursor-not-allowed",
            isLocked && GRAY_BUTTON_STYLING,
          )}
          style={{
            backgroundImage: !isLocked
              ? selected
                ? // We load both images to preload the image that is not currently in front.
                  `linear-gradient(to right, #FEE187 0%, #FEE187 29%, #FEE187C4 42%, #FEE18700 100%), url(${backgroundImageColor}), url(${backgroundImageGrayscale})`
                : `linear-gradient(to right, #D5F9C9 0%, #D5F9C9 29%, #C2E2B7C7 42%, #7E937700 100%), url(${backgroundImageGrayscale}), url(${backgroundImageColor})`
              : undefined,
            backgroundSize: "cover",
            backgroundPosition: "right",
          }}
        >
          {/* Image */}
          {isLocked && (
            <div className="absolute right-2 bottom-0 w-[150px] h-24 overflow-hidden rounded-br-3xl">
              <img
                src={banner.sidebar_asset}
                alt=""
                className={cn(
                  "w-full h-full transform-gpu drop-shadow-[4px_4px_4px_rgba(0,0,0,0.5)] select-none",
                )}
              />
            </div>
          )}
          {/* Border */}
          <div
            className={cn(
              "absolute top-0 left-0 right-0 bottom-0 border-4 border-transparent rounded-tl-3xl rounded-br-3xl",
              selected && !isLocked && "border-[#FEE187]",
            )}
          />
          <div className="relative z-10 w-full h-full flex flex-col pl-5 py-4 box-border rounded-tl-3xl rounded-br-3xl">
            {banner ? (
              <div className="flex gap-4 justify-between">
                <div className="flex flex-col gap-1.5">
                  <div
                    className={cn(
                      "text-xl mb-0.5",
                      isLocked && "text-neutral-500",
                    )}
                  >
                    <div className="flex gap-2 items-center">
                      {banner.name.toUpperCase()}
                      {(banner.puzzle1?.nsfw || banner.puzzle2?.nsfw) && (
                        <NSFWIndicator size="lg" />
                      )}
                    </div>
                  </div>
                  <BannerStatus
                    banner={banner}
                    numGachaSolves={numGachaSolves}
                  />
                </div>
                {(banner.puzzle1.answer || banner.puzzle2.answer) && (
                  <BannerAnswer state={banner} selected={selected} />
                )}
              </div>
            ) : (
              <div>Banner did not load.</div>
            )}
          </div>
        </div>
      </div>
    </button>
  );
}

export default GachaSidebarItem;
