import { cn } from "@hunt/styled-ui";
import { Puzzle } from "lucide-react";
import React from "react";
import first_shell_solved from "../assets/first_shell_solved.svg";
import second_shell_solved from "../assets/second_shell_solved.svg";
import { type GachaPuzzle } from "../types";

const SHELL_STATUS_STYLE = "w-7 h-7 select-none";

type ShellStatusProps = {
  puzzle: GachaPuzzle;
  overrideStatus?: "unlocked" | "locked";
  isFirstPuzzle?: boolean;
  className?: string;
};

const ShellStatus = ({
  puzzle,
  overrideStatus,
  isFirstPuzzle,
  className,
}: ShellStatusProps) => {
  if (puzzle.answer) {
    return (
      <img
        alt="This shell is solved"
        src={isFirstPuzzle ? first_shell_solved : second_shell_solved}
        className={cn(SHELL_STATUS_STYLE, className)}
      />
    );
  }
  if ((overrideStatus || puzzle.state) === "unlocked") {
    return (
      <div
        className="relative w-7 h-7 select-none"
        aria-label="This shell is unsolved"
      >
        <div
          className={cn(
            SHELL_STATUS_STYLE,
            "rounded-full bg-[#8B9F85]",
            className,
          )}
        />
        <Puzzle
          className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-5 h-5 pointer-events-none select-none fill-white"
          strokeWidth={0}
        />
      </div>
    );
  }
  return (
    <div
      className={cn(
        SHELL_STATUS_STYLE,
        "rounded-full bg-neutral-700 flex items-center justify-center pointer-events-none text-white font-bold text-lg select-none",
        className,
      )}
      aria-label="This shell has not been pulled yet"
    >
      ?
    </div>
  );
};

export default ShellStatus;
