import {
  autoUpdate,
  flip,
  offset,
  safePolygon,
  shift,
  useFloating,
  useFocus,
  useHover,
  useInteractions,
  useRole,
} from "@floating-ui/react";
import { cn } from "@hunt/styled-ui";
import React, { useState } from "react";
import { PuzzleTooltipComponent } from "../../../../components/Tooltip";
import {
  type ImageLayer,
  type BannerDisplay,
  type GachaPuzzle,
} from "../types";
import ConditionalLink from "./ConditionalLink";
import ShellStatus from "./ShellStatus";

type GachaOverlayEntityProps = {
  href?: string;
  puzzleArtProps: ImageLayer;
  puzzleStateProps: GachaPuzzle;
  isFirstPuzzle?: boolean;
  glowColor:
    | {
        color: string;
        hover_tailwind: string;
        base_tailwind: string;
      }
    | undefined;
};

const GachaOverlayEntity = ({
  href,
  puzzleArtProps,
  puzzleStateProps,
  isFirstPuzzle,
  glowColor,
}: GachaOverlayEntityProps) => {
  const [showTooltip, setShowTooltip] = useState(false);
  const { refs, floatingStyles, context } = useFloating({
    placement: puzzleStateProps.tooltip_position ?? "top",
    open: showTooltip,
    onOpenChange: setShowTooltip,
    middleware: [offset(10), flip(), shift()],
    whileElementsMounted: autoUpdate,
  });
  const hover = useHover(context, { move: false, handleClose: safePolygon() });
  const focus = useFocus(context);
  const role = useRole(context, { role: "label" });
  const { getReferenceProps, getFloatingProps } = useInteractions([
    hover,
    focus,
    role,
  ]);

  return (
    <>
      <style>{`
        @keyframes pulse-glow-${glowColor?.color?.replace("#", "")} {
          0%, 100% {
            filter: drop-shadow(0 0 4px ${glowColor?.color});
          }
          20% {
            filter: drop-shadow(0 0 8px ${glowColor?.color}) drop-shadow(0 0 12px ${glowColor?.color});
          }
          40% {
            filter: drop-shadow(0 0 4px ${glowColor?.color});
          }
        }
        .gacha-hover-glow-wrapper-${glowColor?.color?.replace("#", "")}:hover {
          filter: drop-shadow(0 0 12px ${glowColor?.color ?? "transparent"});
        }
      `}</style>
      <ConditionalLink
        href={href}
        className={cn(
          "absolute group/puzzle-shell",
          glowColor &&
            puzzleStateProps.state === "unlocked" &&
            `gacha-hover-glow-wrapper-${glowColor?.color?.replace("#", "")}`,
        )}
        style={{
          top: puzzleArtProps?.top,
          left: puzzleArtProps?.left,
          height: puzzleArtProps?.height,
          maxHeight: puzzleArtProps?.height,
          zIndex: puzzleArtProps?.z_index ?? 0,
        }}
        ref={refs.setReference}
        {...getReferenceProps()}
      >
        <img
          src={puzzleArtProps?.src}
          alt=""
          className={cn(
            "object-contain w-auto h-full select-none",
            glowColor?.base_tailwind ?? undefined,
            href && (glowColor?.hover_tailwind ?? undefined),
          )}
          style={{
            ...(!puzzleStateProps.answer &&
              puzzleStateProps.state === "unlocked" && {
                animation: `pulse-glow-${glowColor?.color?.replace("#", "")} 5s ease-in-out infinite`,
              }),
          }}
        />
      </ConditionalLink>
      {showTooltip && (
        <PuzzleTooltipComponent
          innerRef={refs.setFloating}
          style={{
            ...floatingStyles,
            visibility: "visible",
            zIndex: 100,
          }}
          title={puzzleStateProps.title ?? ""}
          answer={puzzleStateProps.answer}
          lockState={puzzleStateProps.state ?? "locked"}
          nsfw={puzzleStateProps.nsfw}
          iconOverride={
            <ShellStatus
              puzzle={puzzleStateProps}
              isFirstPuzzle={isFirstPuzzle}
              className="mr-1"
            />
          }
          {...getFloatingProps()}
        />
      )}
    </>
  );
};

type GachaBannerArtProps = {
  height: string;
  banner: BannerDisplay | undefined;
};

const GachaBannerArt = ({ height, banner }: GachaBannerArtProps) => {
  let fullBanner = banner?.asset_grayscale;
  let puzzle1Art = banner?.puzzle1?.shell_image_grayscale;
  let puzzle2Art = banner?.puzzle2?.shell_image_grayscale;
  let layers = banner?.layers_grayscale;
  if (
    banner?.puzzle1?.answer &&
    banner?.puzzle2?.answer &&
    banner?.asset_color
  ) {
    fullBanner = banner.asset_color;
    puzzle1Art = banner.puzzle1.shell_image_color;
    puzzle2Art = banner.puzzle2.shell_image_color;
    layers = banner?.layers_color;
  }

  const puzzle1Href =
    (banner?.puzzle1?.state === "unlocked" || banner?.puzzle1?.answer) &&
    banner?.puzzle1?.slug
      ? `/puzzles/${banner.puzzle1.slug}`
      : undefined;
  const puzzle2Href =
    (banner?.puzzle2?.state === "unlocked" || banner?.puzzle2?.answer) &&
    banner?.puzzle2?.slug
      ? `/puzzles/${banner.puzzle2.slug}`
      : undefined;

  return (
    <div className="w-fit h-fit relative overflow-hidden rounded-xl">
      <img
        src={fullBanner}
        alt={banner?.alt ?? ""}
        className="object-contain rounded-xl select-none"
        style={{ height }}
        aria-hidden="true"
      />
      {banner?.puzzle1 && puzzle1Art?.src && (
        <GachaOverlayEntity
          href={puzzle1Href}
          puzzleArtProps={puzzle1Art}
          puzzleStateProps={banner?.puzzle1}
          isFirstPuzzle
          glowColor={banner?.glow_color}
        />
      )}
      {banner?.puzzle2 && puzzle2Art?.src && (
        <GachaOverlayEntity
          href={puzzle2Href}
          puzzleArtProps={puzzle2Art}
          puzzleStateProps={banner?.puzzle2}
          glowColor={banner?.glow_color}
        />
      )}
      {layers?.map(({ src, top, left, height, z_index }, i) => {
        return (
          <img
            key={`layer_${i}`}
            src={src}
            alt=""
            className="absolute pointer-events-none select-none"
            style={{
              top: top,
              left: left,
              height: height,
              maxHeight: height,
              zIndex: z_index ?? 0,
            }}
            aria-hidden="true"
          />
        );
      })}
    </div>
  );
};

export default GachaBannerArt;
