import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { NSFWIndicator } from "../../../components/NSFWIndicator";
import redBall from "./assets/red_ball.svg";
import ShellStatus from "./components/ShellStatus";
import { GRAY_BUTTON_STYLING, LONG_GOLD_BUTTON_STYLING } from "./gacha_styling";
import type { GachaPuzzle, CasinoStateWithUI } from "./types";

const BALL_IMAGES = [redBall];

type PuzzleEntryProps = {
  puzzle: GachaPuzzle;
  bannerSlug: string;
  isFirstPuzzle?: boolean;
  forceUnlocked?: boolean;
};

const PuzzleEntryContents = ({
  puzzle,
  bannerSlug,
  isFirstPuzzle,
}: PuzzleEntryProps) => {
  return (
    <div className="flex items-center gap-2 w-full">
      <div className="flex-1 flex items-center gap-2">
        <ShellStatus
          puzzle={puzzle}
          isFirstPuzzle={isFirstPuzzle}
          className="mr-1"
        />
        <span className="font-bold mr-1">{bannerSlug.toUpperCase()}:</span>
        <span className="text-left font-medium">{puzzle.title}</span>
        {puzzle.nsfw && <NSFWIndicator size="md" />}
      </div>
      {puzzle.answer && (
        <span className="ml-2 text-green-500 text-right flex-shrink-0">
          {puzzle.answer}
        </span>
      )}
    </div>
  );
};

const PuzzleEntry = ({
  puzzle,
  bannerSlug,
  isFirstPuzzle,
  forceUnlocked = false,
}: PuzzleEntryProps) => {
  return forceUnlocked || puzzle.state === "unlocked" || puzzle.answer ? (
    <a
      role="button"
      key={puzzle.slug}
      href={`/puzzles/${puzzle.slug}`}
      className={cn(
        "flex items-center gap-2 p-2 rounded-lg transition text-lg font-semibold text-white w-full max-w-xl hover:text-white hover:brightness-125 focus-visible:brightness-125 hover:scale-[1.02] focus-visible:scale-[1.02]",
        GRAY_BUTTON_STYLING,
      )}
    >
      <PuzzleEntryContents
        puzzle={puzzle}
        bannerSlug={bannerSlug}
        isFirstPuzzle={isFirstPuzzle}
      />
    </a>
  ) : (
    <ConditionalTooltip tooltip="You have not pulled this shell yet.">
      <div
        key={puzzle.slug}
        aria-disabled="true"
        className={cn(
          "flex items-center gap-2 p-2 rounded-lg text-lg font-semibold text-white w-full max-w-xl brightness-50 opacity-75 cursor-not-allowed",
          GRAY_BUTTON_STYLING,
        )}
      >
        <PuzzleEntryContents
          puzzle={puzzle}
          bannerSlug={bannerSlug}
          isFirstPuzzle={isFirstPuzzle}
        />
      </div>
    </ConditionalTooltip>
  );
};

type GachaPuzzleListProps = {
  state: CasinoStateWithUI;
  unlockAllPuzzlesAndBanners?: boolean;
};

const GachaPuzzleList = ({
  state,
  unlockAllPuzzlesAndBanners = false,
}: GachaPuzzleListProps) => {
  return (
    <div className="relative w-full h-full flex justify-center items-center">
      <ul className="flex flex-col items-center gap-4 w-full p-8">
        {(unlockAllPuzzlesAndBanners || state.meta?.state === "unlocked") &&
          state.meta && (
            <li className="w-fit">
              <a
                role="button"
                href={`/puzzles/${state.meta.slug}`}
                className={cn(
                  "flex flex-col p-2 px-12 items-center justify-center rounded-lg transition text-lg font-semibold text-white hover:text-white hover:brightness-125 hover:scale-105",
                  LONG_GOLD_BUTTON_STYLING,
                )}
              >
                <div className="flex flex-wrap justify-center text-center items-center gap-2 text-2xl">
                  Meta: <span className="font-normal">{state.meta.title}</span>
                </div>
                {state.meta.answer && (
                  <span className="text-green-400">{state.meta.answer}</span>
                )}
              </a>
            </li>
          )}
        {state.banners.map((banner, bannerIndex) => {
          return unlockAllPuzzlesAndBanners || banner.state === "unlocked" ? (
            <li key={banner.slug} className="w-full max-w-xl">
              <div className="relative">
                <img
                  src={BALL_IMAGES[bannerIndex % BALL_IMAGES.length]}
                  alt=""
                  aria-hidden="true"
                  className="pointer-events-none absolute top-1/2 h-36 -translate-x-1/2 -translate-y-1/2 object-contain z-0 select-none"
                />
                <div className="relative z-10 flex flex-col gap-2">
                  <PuzzleEntry
                    puzzle={banner.puzzle1}
                    bannerSlug={banner.slug}
                    isFirstPuzzle
                    forceUnlocked={unlockAllPuzzlesAndBanners}
                  />
                  <PuzzleEntry
                    puzzle={banner.puzzle2}
                    bannerSlug={banner.slug}
                    forceUnlocked={unlockAllPuzzlesAndBanners}
                  />
                </div>
              </div>
            </li>
          ) : null;
        })}
      </ul>
    </div>
  );
};

export default GachaPuzzleList;
