import { cn } from "@hunt/styled-ui";
import React, { forwardRef } from "react";

type ConditionalLinkProps = {
  href?: string;
  children: React.ReactNode;
} & (
  | React.AnchorHTMLAttributes<HTMLAnchorElement>
  | React.HTMLAttributes<HTMLDivElement>
);

/**
 * If a link is provided, use the HTML <a> tag.
 * Otherwise, use a <div> tag.
 */
const ConditionalLink = forwardRef<
  HTMLAnchorElement | HTMLDivElement,
  ConditionalLinkProps
>(({ href, children, className, ...otherProps }, ref) => {
  if (href) {
    return (
      <a
        ref={ref as React.Ref<HTMLAnchorElement>}
        href={href}
        className={className}
        {...(otherProps as React.AnchorHTMLAttributes<HTMLAnchorElement>)}
      >
        {children}
      </a>
    );
  }

  return (
    <div
      ref={ref as React.Ref<HTMLDivElement>}
      className={cn("cursor-not-allowed", className)}
      {...(otherProps as React.HTMLAttributes<HTMLDivElement>)}
    >
      {children}
    </div>
  );
});

ConditionalLink.displayName = "ConditionalLink";

export default ConditionalLink;
