import { cn } from "@hunt/styled-ui";
import { RED_BUTTON_STYLING } from "../gacha_styling";
import { GACHA_QUERY_KEYS } from "../useGachaQueryParam";
import { GachaActionLink } from "./GachaActionButton";

type QuestButtonProps = {
  selectedBanner: string | undefined;
  size?: "sm" | "lg";
};

function QuestButton({ selectedBanner, size = "sm" }: QuestButtonProps) {
  return (
    <GachaActionLink
      href={`/rounds/fates_thread_casino/quests?${GACHA_QUERY_KEYS.BANNER}=${selectedBanner}`}
      className={cn(
        RED_BUTTON_STYLING,
        size === "sm" ? "h-[42px] w-fit text-sm" : "w-80",
      )}
    >
      {size === "lg" ? "Quests to earn chips" : "Quests"}
    </GachaActionLink>
  );
}

export default QuestButton;
