import { useEffect, useState } from "react";

export function useHintUnlockState(hintsUnlockedAt?: string) {
  const [unlocked, setUnlocked] = useState(false);

  useEffect(() => {
    if (!hintsUnlockedAt) {
      setUnlocked(false);
      return;
    }

    const unlockAt = new Date(hintsUnlockedAt).getTime();
    const now = Date.now();
    if (unlockAt <= now) {
      setUnlocked(true);
      return;
    }

    setUnlocked(false);
    const timeout = setTimeout(() => {
      setUnlocked(true);
    }, unlockAt - now);

    return () => {
      clearTimeout(timeout);
    };
  }, [hintsUnlockedAt]);

  return unlocked;
}
