import { type TeamHuntState } from "@hunt/public-client";
import {
  type ResolvedCutsceneContent,
  CutsceneDisplay,
} from "@hunt/puzzle-components";
import { ConditionalTooltip } from "@hunt/shadcn";
import { type ParsedQs } from "qs";
import React, { useEffect, useState, useMemo } from "react";
import { TeamStateProvider } from "../../../components/TeamStateProvider";
import {
  deleteQueryParam,
  updateQueryParam,
} from "../../../rounds/query_param_utils";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import GachaPuzzleList from "./GachaPuzzleList";
import { WordsFont } from "./Words";
import { GACHA_ART_CREDITS } from "./art_credits";
import HelpIcon from "./assets/HelpIcon";
import { GachaActionLink } from "./components/GachaActionButton";
import GachaBannerArt from "./components/GachaBannerArt";
import { GachaProgressBarInBanner } from "./components/GachaProgressBar";
import GachaSidebarItem from "./components/GachaSidebarItem";
import PullButtons, { type PullBannerResult } from "./components/PullButtons";
import PullInfo from "./components/PullInfo";
import QuestButton from "./components/QuestButton";
import {
  buildUnlockAllBannerDisplay,
  buildUnlockAllMetaDisplay,
} from "./gacha_state";
import { CASINO_BACKGROUND_STYLE } from "./gacha_styling";
import GachaTutorial from "./tutorial/GachaTutorial";
import type { CasinoStateWithUI } from "./types";
import useGachaQueryParams, { GACHA_QUERY_KEYS } from "./useGachaQueryParam";
import { useHintUnlockState } from "./useHintUnlockState";

const UnlockAllToggle = ({
  enabled,
  onToggle,
}: {
  enabled: boolean;
  onToggle: () => void;
}) => {
  const modePrefix = enabled ? "Archive Mode:" : "Live Hunt Mode:";
  const modeDetail = enabled
    ? "Showing all puzzles & banners"
    : "Showing unlocked puzzles & banners";
  return (
    <button
      type="button"
      onClick={onToggle}
      className="flex items-center gap-3 text-sm uppercase tracking-wide text-white"
      aria-pressed={enabled}
      aria-label={
        enabled
          ? "Archive Mode: Show all puzzles & banners"
          : "Live Hunt Mode: Show unlocked puzzles & banners"
      }
    >
      <span className="w-72 text-right leading-tight whitespace-normal">
        <span>{modePrefix}</span>
        <br />
        <span>{modeDetail}</span>
      </span>
      <div
        className={`w-[54px] h-[28px] rounded-full flex items-center p-1 cursor-pointer transition-colors shadow-[inset_0_4px_4px_rgba(0,0,0,0.55)] ${enabled ? "bg-[#C62828]" : "bg-[#FEE187]"}`}
      >
        <div
          className={`w-[22px] h-[22px] bg-[#B6D0F3] rounded-full transition-all duration-200 ease-in-out ${enabled ? "translate-x-[24px]" : "translate-x-0"}`}
        />
      </div>
    </button>
  );
};

const GachaBody = ({
  state,
  teamState,
  queryParams,
  numChips,
  cutsceneContent,
  onPull,
}: {
  state: CasinoStateWithUI;
  teamState: TeamHuntState;
  queryParams?: ParsedQs | URLSearchParams;
  numChips: number;
  cutsceneContent?: ResolvedCutsceneContent[];
  onPull?: (args: {
    bannerSlug: string;
    numPulls: number;
  }) => Promise<{ pulls: PullBannerResult[]; error?: string }>;
}) => {
  const { banner } = useGachaQueryParams(queryParams);
  const [selectedBanner, setSelectedBanner] = useState(banner);
  const [pullResults, setPullResults] = useState<PullBannerResult[] | null>(
    null,
  );
  const [unlockAllPuzzlesAndBanners, setUnlockAllPuzzlesAndBanners] =
    useState(false);

  const displayedBanners: CasinoStateWithUI["banners"] =
    useMemo((): CasinoStateWithUI["banners"] => {
      if (!IS_STATIC_SITE || !unlockAllPuzzlesAndBanners) {
        return state.banners;
      }
      return buildUnlockAllBannerDisplay({
        teamState,
        banners: state.banners,
      });
    }, [state.banners, teamState, unlockAllPuzzlesAndBanners]);

  const selectedBannerData = useMemo(() => {
    return displayedBanners.find((b) => b.slug === selectedBanner);
  }, [displayedBanners, selectedBanner]);

  const displayedMeta: CasinoStateWithUI["meta"] =
    useMemo((): CasinoStateWithUI["meta"] => {
      if (!IS_STATIC_SITE || !unlockAllPuzzlesAndBanners) {
        return state.meta;
      }
      const unlockAllMeta: CasinoStateWithUI["meta"] =
        buildUnlockAllMetaDisplay({
          teamState,
          currentMeta: state.meta,
        });
      return unlockAllMeta;
    }, [state.meta, teamState, unlockAllPuzzlesAndBanners]);

  useEffect(() => {
    if (selectedBanner) {
      updateQueryParam(GACHA_QUERY_KEYS.BANNER, selectedBanner ?? "", true);
    } else if (displayedBanners[0].slug) {
      // If no banner is selected, default to the first one.
      const firstBannerSlug = displayedBanners[0].slug;
      setSelectedBanner(firstBannerSlug);
      updateQueryParam(GACHA_QUERY_KEYS.BANNER, firstBannerSlug, true);
    } else {
      // This case shouldn't happen because teams start with two banners unlocked.
      deleteQueryParam(GACHA_QUERY_KEYS.BANNER, true);
    }
  }, [displayedBanners, selectedBanner]);

  useEffect(() => {
    if (unlockAllPuzzlesAndBanners) return;
    const selectedBannerState = state.banners.find(
      (b) => b.slug === selectedBanner,
    );
    if (selectedBannerState?.state === "locked") {
      const firstUnlocked = state.banners.find((b) => b.state === "unlocked");
      if (firstUnlocked) {
        setSelectedBanner(firstUnlocked.slug);
      }
    }
  }, [selectedBanner, state.banners, unlockAllPuzzlesAndBanners]);

  const progress = useMemo(() => {
    return selectedBanner && selectedBannerData && selectedBannerData.slug
      ? state.banner_progress.find(
          (p) => p.banner_slug === selectedBannerData.slug,
        )
      : undefined;
  }, [selectedBanner, selectedBannerData, state.banner_progress]);

  const hintHref = useMemo(() => {
    return selectedBanner
      ? `/rounds/fates_thread_casino/hints?${GACHA_QUERY_KEYS.BANNER}=${encodeURIComponent(selectedBanner)}`
      : undefined;
  }, [selectedBanner]);
  const bannerHintsUnlockedAt = useMemo(
    () =>
      selectedBanner
        ? state.banner_hints_unlocked_at?.[selectedBanner]
        : undefined,
    [selectedBanner, state.banner_hints_unlocked_at],
  );
  const hintsUnlocked = useHintUnlockState(bannerHintsUnlockedAt);
  const hintAvailableAt = useMemo(() => {
    if (!bannerHintsUnlockedAt) {
      return undefined;
    }
    return new Date(bannerHintsUnlockedAt).toLocaleString("en-US");
  }, [bannerHintsUnlockedAt]);
  let hintTooltip: string | undefined;
  if (bannerHintsUnlockedAt) {
    if (hintsUnlocked) {
      hintTooltip = "Ask for a hint";
    } else {
      hintTooltip = `Hints will be available for this banner at ${hintAvailableAt}`;
    }
  } else {
    hintTooltip = undefined;
  }
  const hint =
    bannerHintsUnlockedAt && hintHref
      ? {
          href: hintHref,
          disabled: !hintsUnlocked,
          tooltip: hintTooltip,
        }
      : undefined;

  const credits =
    GACHA_ART_CREDITS[selectedBanner as keyof typeof GACHA_ART_CREDITS];

  return (
    <TeamStateProvider teamState={teamState}>
      <WordsFont />
      <div
        id="main-content"
        className="flex flex-col min-h-screen w-screen overflow-x-auto"
        style={CASINO_BACKGROUND_STYLE}
      >
        <div
          className="w-fit pt-16 px-8 mx-auto"
          id="fates-thread-casino-tutorial-container"
        >
          <div className="flex flex-col gap-4 mt-12 pb-2 min-w-max items-center">
            <div className="flex flex-col gap-2 w-fit min-w-[1260.71px]">
              <div className="pl-3.5 w-full flex justify-between items-center">
                <div data-tutorial="quest-button">
                  <QuestButton selectedBanner={selectedBanner} size="lg" />
                </div>
                {displayedMeta && (
                  <GachaActionLink
                    href={`/puzzles/${displayedMeta.slug}`}
                    variant="long-gold"
                    className="w-fit px-12"
                  >
                    Meta:{" "}
                    <span className="font-normal">{displayedMeta.title}</span>
                  </GachaActionLink>
                )}
                <div className="flex items-center">
                  <GachaTutorial
                    queryParams={queryParams}
                    entrypoint={(startTutorial) => {
                      return (
                        <ConditionalTooltip tooltip="Tutorial">
                          <button
                            aria-label="Click for tutorial"
                            onClick={startTutorial}
                            className="ml-4 select-none"
                          >
                            <HelpIcon className="w-14 p-1 fill-white hover:fill-neutral-500 hover:p-0" />
                          </button>
                        </ConditionalTooltip>
                      );
                    }}
                  />
                  <div data-tutorial="currency">
                    <PullInfo numChips={numChips} />
                  </div>
                </div>
              </div>
              <div className="flex flex-row gap-1.5 w-fit justify-center mt-2">
                {/* Sidebar */}
                <div className="flex flex-col gap-2" data-tutorial="banners">
                  {displayedBanners.map((banner) => (
                    <GachaSidebarItem
                      key={banner.slug}
                      banner={banner}
                      onClick={() => {
                        setSelectedBanner(banner.slug);
                      }}
                      numGachaSolves={state.num_solves ?? 0}
                      selected={selectedBanner === banner.slug}
                    />
                  ))}
                </div>
                {/* Main Section */}
                <div className="flex flex-col items-end gap-1">
                  <div
                    className="relative flex items-center justify-center"
                    data-tutorial="banner-art"
                  >
                    {displayedBanners
                      .filter((banner) => banner.state !== "locked")
                      .map((banner) => {
                        const isSelected = banner.slug === selectedBanner;
                        return (
                          <div
                            key={banner.slug}
                            className={
                              isSelected
                                ? "relative block pointer-events-auto"
                                : "absolute inset-0 flex items-center justify-center hidden pointer-events-none"
                            }
                            aria-hidden={!isSelected}
                          >
                            <GachaBannerArt
                              height={`${displayedBanners.length * (24 * 4 + 8) - 8}px`}
                              banner={banner}
                            />
                          </div>
                        );
                      })}
                    <div className="absolute bottom-0 right-0 z-10">
                      {progress ? (
                        <div data-tutorial="clues">
                          <GachaProgressBarInBanner
                            num_clues_pulled={progress.num_clues_pulled}
                            total_clues={progress.total_clues}
                            hint={hint}
                          />
                        </div>
                      ) : null}
                    </div>
                  </div>
                  {credits && (
                    <div className="text-xs italic text-[#0C4D00] flex gap-1 z-10 justify-end mr-1">
                      <span>Banner art: {credits.banner}</span>
                      <span>•</span>
                      <span>Keeper art: {credits.keeper}</span>
                    </div>
                  )}
                </div>
              </div>
              <div className="grid grid-cols-[1fr_auto_1fr] items-start w-full ml-3.5">
                <div
                  className="flex flex-row gap-4 h-fit justify-self-start"
                  data-tutorial="gallery-and-history"
                >
                  <GachaActionLink
                    href={`/rounds/fates_thread_casino/pull_history?${GACHA_QUERY_KEYS.BANNER}=${selectedBanner}`}
                    variant="gold"
                  >
                    Pull History
                  </GachaActionLink>
                  <GachaActionLink
                    href={`/rounds/fates_thread_casino/gallery?${GACHA_QUERY_KEYS.BANNER}=${selectedBanner}`}
                    variant="gold"
                  >
                    Gallery
                  </GachaActionLink>
                </div>
                <div className="justify-self-center pt-1">
                  {IS_STATIC_SITE && (
                    <UnlockAllToggle
                      enabled={unlockAllPuzzlesAndBanners}
                      onToggle={() => {
                        setUnlockAllPuzzlesAndBanners((prev) => !prev);
                      }}
                    />
                  )}
                </div>
                <div className="justify-self-end">
                  <PullButtons
                    numChips={numChips}
                    selectedBanner={selectedBanner}
                    isBannerEmpty={!!progress?.empty}
                    pullResults={pullResults}
                    setPullResults={setPullResults}
                    banners={displayedBanners}
                    onPull={onPull}
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Puzzle list */}
          <GachaPuzzleList
            state={
              displayedMeta
                ? { ...state, banners: displayedBanners, meta: displayedMeta }
                : { ...state, banners: displayedBanners }
            }
            unlockAllPuzzlesAndBanners={
              IS_STATIC_SITE && unlockAllPuzzlesAndBanners
            }
          />
        </div>
      </div>
      <CutsceneDisplay content={cutsceneContent} />
    </TeamStateProvider>
  );
};

export default GachaBody;
