import { type TeamHuntState } from "@hunt/public-client";
import { type ResolvedCutsceneContent } from "@hunt/puzzle-components";
import React, { useCallback, useEffect, useState } from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import useDataset from "../../../client/useDataset";
import { useSolvedPuzzlesState } from "../../../components/puzzleSolveLocalState";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import GachaBody from "./GachaBody";
import { mergeCasinoState, mergeTeamStateIntoCasinoUI } from "./clientUtils";
import {
  applyGachaPullGetAndSet,
  buildLocalCasinoState,
} from "./gachaLocalState";
import type { CasinoStateWithUI } from "./types";
import { useGachaLocalState } from "./useGachaLocalState";

const GachaManager = ({
  initialCasinoState,
  initialTeamState,
  queryParams,
  initialCutsceneContent,
}: {
  initialCasinoState: CasinoStateWithUI;
  initialTeamState: TeamHuntState;
  queryParams: URLSearchParams;
  initialCutsceneContent?: ResolvedCutsceneContent[];
}) => {
  // Use websocket data for real-time updates
  const teamState = useDataset("team_state", undefined, initialTeamState);
  const wsState = useDataset("fates_thread_casino", undefined, {
    epoch: initialCasinoState.epoch,
    available_pulls: initialCasinoState.available_pulls,
    num_solves: initialCasinoState.num_solves,
    banner_progress: initialCasinoState.banner_progress,
  });

  const [state, setState] = useState<CasinoStateWithUI>(initialCasinoState);
  const { solvedMap } = useSolvedPuzzlesState();
  const { localState, setLocalState } = useGachaLocalState();

  useEffect(() => {
    if (IS_STATIC_SITE) return;
    setState((currentState) => mergeCasinoState(wsState, currentState));
  }, [wsState]);

  useEffect(() => {
    if (IS_STATIC_SITE) return;
    setState((currentState) =>
      mergeTeamStateIntoCasinoUI(teamState, currentState),
    );
  }, [teamState]);

  useEffect(() => {
    if (!IS_STATIC_SITE || !localState) return;
    const nextState = buildLocalCasinoState({
      teamState,
      localState,
      solvedMap,
    });
    setState(nextState);
  }, [localState, solvedMap, teamState]);

  const handleLocalPull = useCallback(
    async ({
      bannerSlug,
      numPulls,
    }: {
      bannerSlug: string;
      numPulls: number;
    }) => {
      const { nextState, pullResults, error } = await applyGachaPullGetAndSet({
        bannerSlug,
        numPulls,
      });
      if (error) {
        return { pulls: [], error };
      }
      setLocalState(nextState);
      const nextUiState = buildLocalCasinoState({
        teamState,
        localState: nextState,
        solvedMap,
      });
      setState(nextUiState);
      return { pulls: pullResults };
    },
    [setLocalState, solvedMap, teamState],
  );

  const numChips = state.available_pulls ?? 0;

  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GachaBody
        state={state}
        teamState={teamState}
        queryParams={queryParams}
        numChips={numChips}
        cutsceneContent={initialCutsceneContent}
        onPull={IS_STATIC_SITE ? handleLocalPull : undefined}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("fates-thread-casino-root");
if (elem) {
  const {
    initialCasinoState: state,
    initialTeamState: teamState,
    initialCutsceneContent,
  } = window as unknown as {
    initialCasinoState: CasinoStateWithUI;
    initialTeamState: TeamHuntState;
    initialCutsceneContent?: ResolvedCutsceneContent[];
  };
  const queryParams = new URLSearchParams(window.location.search);
  hydrateRoot(
    elem,
    <GachaManager
      initialCasinoState={state}
      initialTeamState={teamState}
      queryParams={queryParams}
      initialCutsceneContent={initialCutsceneContent}
    />,
  );
} else {
  console.error(
    "Could not mount Fate's Thread Casino Manager because #fates-thread-casino-root was nowhere to be found",
  );
}
