import { useGlobalVolume } from "@hunt/puzzle-components";
import { SkipForward, Volume2, VolumeX, X } from "lucide-react";
import React, { useCallback, useEffect, useRef, useState } from "react";
import ReactDOM from "react-dom";
import pullAnimationVideo from "../assets/pull_animation/pull_animation.mp4";
import pullAnimation10Video from "../assets/pull_animation/pull_animation_10.mp4";

const MUTED_STORAGE_KEY = "overlay-muted";
const VOLUME_STORAGE_KEY = "overlay-volume";

type PullAnimationOverlayProps = {
  clueComponents: (string | null)[];
  shellComponents: React.ReactNode[];
  onClose?: () => void; // Optional callback for when overlay is closed
  type: "1" | "10";
};

const PullAnimationOverlay: React.FC<PullAnimationOverlayProps> = ({
  clueComponents,
  shellComponents,
  onClose,
  type,
}) => {
  const portalRootRef = useRef<HTMLDivElement | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const listenerSetupRef = useRef(false);
  const [revealClues, setRevealClues] = useState(false);
  const [videoReady, setVideoReady] = useState(false);

  // 🔊 state for audio settings
  const [muted, setMuted] = useState<boolean>(() => {
    const stored = localStorage.getItem(MUTED_STORAGE_KEY);
    return stored === "true";
  });
  const globalVolume = useGlobalVolume();

  const [volume, setVolume] = useState<number>(() => {
    const stored = localStorage.getItem(VOLUME_STORAGE_KEY);
    return stored ? parseFloat(stored) : globalVolume;
  });

  // Refs to track latest muted/volume values for event handlers
  const mutedRef = useRef(muted);
  const volumeRef = useRef(volume);

  // Keep refs in sync with state
  useEffect(() => {
    mutedRef.current = muted;
    volumeRef.current = volume;
  }, [muted, volume]);

  // Apply mute/volume whenever they change
  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.muted = muted;
      videoRef.current.volume = volume;
    }
    localStorage.setItem(MUTED_STORAGE_KEY, String(muted));
    localStorage.setItem(VOLUME_STORAGE_KEY, String(volume));
  }, [muted, volume]);

  // Create portal root div and disable body scroll
  useEffect(() => {
    // Store original overflow style to restore later
    const originalOverflow = document.body.style.overflow;

    // Disable scrolling
    document.body.style.overflow = "hidden";

    const root = document.createElement("div");
    root.style.position = "fixed";
    root.style.inset = "0";
    root.style.zIndex = "1000";
    portalRootRef.current = root;
    document.body.appendChild(root);

    return () => {
      // Restore original overflow style
      document.body.style.overflow = originalOverflow;

      if (portalRootRef.current?.parentElement) {
        portalRootRef.current.parentElement.removeChild(portalRootRef.current);
      }
      portalRootRef.current = null;
    };
  }, [type]);

  // Skip → jump to reveal state
  const handleSkip = () => {
    // Start fade transition
    setRevealClues(true);
    videoRef.current?.pause();
  };

  // Video ended → fade to black then reveal state
  const handleEnded = () => {
    setRevealClues(true);
    videoRef.current?.pause();
  };

  // Close overlay
  const handleClose = useCallback(() => {
    if (portalRootRef.current?.parentElement) {
      portalRootRef.current.parentElement.removeChild(portalRootRef.current);
    }
    onClose?.();
  }, [onClose]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        handleClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [handleClose]);

  // Set up video ready listener when video ref is available
  useEffect(() => {
    const onVideoReady = () => {
      setVideoReady(true);
      // Apply volume and mute settings when video is ready (use refs to get latest values)
      if (videoRef.current) {
        videoRef.current.muted = mutedRef.current;
        videoRef.current.volume = volumeRef.current;
      }
      void videoRef.current?.play();
    };

    const video = videoRef.current;
    if (video && !listenerSetupRef.current) {
      listenerSetupRef.current = true;
      // If video is already ready, apply settings immediately
      if (video.readyState >= video.HAVE_FUTURE_DATA) {
        onVideoReady();
      } else {
        video.addEventListener("canplaythrough", onVideoReady);
        return () => {
          listenerSetupRef.current = false;
          video.removeEventListener("canplaythrough", onVideoReady);
        };
      }
    }
  }); // Run on every render to catch when video ref becomes available

  // Update video settings when muted/volume change (for when video is already ready)
  useEffect(() => {
    if (videoRef.current && videoReady) {
      videoRef.current.muted = muted;
      videoRef.current.volume = volume;
    }
  }, [muted, volume, videoReady]);

  if (!portalRootRef.current) return null;

  return ReactDOM.createPortal(
    <div className="cash-animation-content relative w-full h-full bg-black flex flex-col items-center justify-center">
      <style>{`
        @keyframes rotation {
          0% {
              transform: rotate(0deg);
          }
          100% {
              transform: rotate(360deg);
          }
        }
      `}</style>
      {/* Video container */}
      <div className="absolute w-full h-full z-0">
        {!videoReady && (
          <div className="relative w-full h-full">
            <div
              className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full w-16 h-16 border-4 border-white border-b-[#6FA078]"
              style={{
                animation: "rotation 2s linear infinite",
              }}
            />
          </div>
        )}
        <video
          ref={videoRef}
          onEnded={handleEnded}
          className="w-full h-full select-none"
          aria-label="Animation of a gacha machine ejecting a capsule containing the pulled clue or clues."
        >
          <track kind="captions" src="" label="No captions" />
          <source
            src={type === "1" ? pullAnimationVideo : pullAnimation10Video}
            type="video/mp4"
          />
        </video>

        {/* Skip button */}
        <button
          onClick={handleSkip}
          className="absolute top-4 right-4 bg-white flex gap-2 justify-center text-black text-2xl px-5 py-2 rounded shadow-lg hover:bg-gray-300 transition-colors z-10 select-none"
          aria-label="Skip to view pulled clues"
        >
          Skip
          <SkipForward width={32} height={32} />
        </button>

        {/* 🔊 Volume controls */}
        <div className="absolute top-4 left-4 flex items-center gap-2 bg-black/70 p-2 rounded z-10">
          <button
            onClick={() => {
              setMuted((m) => !m);
            }}
            className="text-white hover:scale-110 transition-transform select-none"
            aria-label={muted ? "Unmute" : "Mute"}
          >
            {muted || volume === 0 ? (
              <VolumeX width={32} height={32} />
            ) : (
              <Volume2 width={32} height={32} />
            )}
          </button>
          <input
            type="range"
            min={0}
            max={1}
            step={0.05}
            value={volume}
            onChange={(e) => {
              const newVolume = parseFloat(e.target.value);
              setVolume(newVolume);
              // Auto-mute when volume is 0, auto-unmute when volume > 0
              if (newVolume === 0) {
                setMuted(true);
              } else if (muted && newVolume > 0) {
                setMuted(false);
              }
            }}
            className="w-24 cursor-pointer select-none"
          />
        </div>

        {/* Animation credit */}
        {videoReady && !revealClues && (
          <div className="absolute bottom-4 left-4 text-white text-sm bg-black/70 px-3 py-2 rounded z-10">
            Animation by Chris Yip
          </div>
        )}
      </div>

      <div
        className={`absolute z-1 w-full h-full bg-black flex flex-col items-center gap-4 p-4 overflow-y-auto transition-opacity duration-500 ${revealClues ? "opacity-100" : "opacity-0 pointer-events-none"}`}
      >
        {/* Close button - positioned absolutely to stay on top */}
        <button
          onClick={handleClose}
          className="fixed top-4 right-4 z-[10002] bg-white border-2 border-black
                   rounded-full w-10 h-10 flex items-center justify-center text-black
                   hover:bg-red-500 hover:text-white transition-transform duration-150
                   ease-out focus-visible:scale-125 hover:scale-125 origin-center select-none"
          aria-label="Close clue overlay"
        >
          <X strokeWidth={2.5} />
        </button>

        {/* Shell components */}
        {shellComponents.length > 0 && (
          <div className="flex flex-wrap justify-center gap-4 p-16 pb-0 max-w-screen w-full m-auto">
            {shellComponents.map((shellComponent) => {
              return shellComponent;
            })}
          </div>
        )}

        {/* Clue components */}
        {clueComponents.length > 0 && (
          <div className="flex flex-wrap justify-center gap-4 p-12 max-w-screen w-full m-auto select-none">
            {clueComponents.map(
              (clue, idx) =>
                clue && (
                  <div
                    key={idx}
                    className="w-fit drop-shadow-[0_0_18px_white]"
                    dangerouslySetInnerHTML={{ __html: clue }}
                  />
                ),
            )}
          </div>
        )}
      </div>
    </div>,
    portalRootRef.current,
  );
};

export default PullAnimationOverlay;
